<?php
 namespace Pterodactyl\Http\Controllers\Api\Client\Servers; use Throwable; use Pterodactyl\Models\Server; use Illuminate\Http\JsonResponse; use Illuminate\Support\Facades\Cache; use Pterodactyl\Jobs\Dezerx\RenderRegionMap; use Pterodactyl\Services\Dezerx\Minecraft\Nbt; use Pterodactyl\Services\Dezerx\Minecraft\Worlds; use Pterodactyl\Services\Dezerx\Minecraft\BlueMap; use Pterodactyl\Services\Dezerx\Minecraft\RegionFile; use Pterodactyl\Services\Dezerx\Minecraft\ServerFiles; use Pterodactyl\Services\Dezerx\Minecraft\ServerPlatform; use Pterodactyl\Http\Controllers\Api\Client\ClientApiController; use Pterodactyl\Http\Requests\Api\Client\Servers\Worlds\WorldRequest; use Pterodactyl\Http\Requests\Api\Client\Servers\Worlds\WorldWriteRequest; use Pterodactyl\Http\Requests\Api\Client\Servers\Worlds\WorldDeleteRequest; class WorldViewerController extends ClientApiController { private const MAX_NBT = 4_000_000; public function worlds(WorldRequest $request, Server $server): JsonResponse { return new JsonResponse(Worlds::list(new ServerFiles($server), $server->uuid)); } public function bluemap(WorldRequest $request, Server $server): JsonResponse { $status = Cache::get("dezerx:bluemap:{$server->uuid}"); if ($status === null) { $status = $this->bluemapStatus(new ServerFiles($server)); if ($status['supported']) { Cache::put("dezerx:bluemap:{$server->uuid}", $status, BlueMap::STATUS_TTL); } } if ($status['supported'] ?? false) { $status['token'] = BlueMap::token($server, (int) $request->user()->id); $status['owner'] = (int) $request->user()->id === (int) $server->owner_id; } return new JsonResponse($status); } private function bluemapStatus(ServerFiles $files): array { $detected = ServerPlatform::detect($files); if ($detected === null) { return [ 'supported' => false, 'message' => 'This server does not look like Paper, Spigot, Fabric, Forge or NeoForge, so there is no BlueMap build for it.', ]; } $platform = $detected['platform']; $minecraft = BlueMap::minecraft($files); $release = BlueMap::release($platform, $minecraft); $installed = BlueMap::installed($files, $detected['directory']); if ($release === null && $installed === null && $minecraft !== null && BlueMap::catalogue($platform) !== null) { return [ 'supported' => false, 'message' => "BlueMap has no {$platform} build for Minecraft {$minecraft}, and the newest one would only crash the server. Move the server to a version BlueMap supports, or wait for a build.", ]; } return [ 'supported' => true, 'platform' => $platform, 'minecraft' => $minecraft, 'directory' => $detected['directory'], 'installed' => $installed, 'version' => $release['version'] ?? null, 'filename' => $release['filename'] ?? null, 'port' => BlueMap::cachedAddress($files)['port'] ?? null, ]; } public function install(WorldWriteRequest $request, Server $server): JsonResponse { BlueMap::forget($server->uuid); $files = new ServerFiles($server); $detected = ServerPlatform::detect($files); if ($detected === null) { return $this->refuse('This server has no BlueMap build.', 422); } $platform = $detected['platform']; $directory = $detected['directory']; $minecraft = BlueMap::minecraft($files); $release = BlueMap::release($platform, $minecraft); if ($release === null) { return $minecraft !== null && BlueMap::catalogue($platform) !== null ? $this->refuse("BlueMap has no {$platform} build for Minecraft {$minecraft}, and the newest one would only crash the server, so nothing was installed.", 422) : $this->refuse('That release could not be reached.', 504); } if (!$files->pullFile($directory, $release['url'], $release['filename'])) { return $this->refuse('The node would not accept that download.', 502); } $files->deletePaths($directory, array_values(array_filter( BlueMap::jars($files, $directory, BlueMap::RELEASE_JAR), fn (string $name) => $name !== $release['filename'], ))); $dependency = BlueMap::dependency($platform, $minecraft); $pulled = $dependency !== null && BlueMap::jars($files, $directory, '/^fabric-api.*\.jar$/i') === [] && $files->pullFile($directory, $dependency['url'], $dependency['filename']) ? $dependency['filename'] : null; $extra = $pulled === null ? '' : " {$pulled} went in with it, BlueMap needs Fabric API."; $allocation = BlueMap::cachedAddress($files) ?? ServerPlatform::claimPort($files); if ($allocation === null) { return new JsonResponse([ 'installed' => true, 'file' => $release['filename'], 'dependency' => $pulled, 'minecraft' => $minecraft, 'message' => "{$release['filename']} is installing, but no port could be claimed, the server may be at its allocation limit. Add one in Network, then set it in BlueMap's webserver.conf.{$extra}", ], 202); } $configured = BlueMap::configure($files, $platform, $allocation['port']); BlueMap::forget($server->uuid); return new JsonResponse([ 'installed' => true, 'file' => $release['filename'], 'dependency' => $pulled, 'minecraft' => $minecraft, 'port' => $allocation['port'], 'ip' => $allocation['ip'], 'configured' => $configured, 'message' => ($configured ? "Installed {$release['filename']} and pointed its web server at {$allocation['ip']}:{$allocation['port']}. Restart the server to start rendering." : "Installed {$release['filename']} and claimed port {$allocation['port']}, but its config could not be written. Set the port in webserver.conf by hand.").$extra, ], 202); } public function nbt(WorldRequest $request, Server $server): JsonResponse { $file = Worlds::safePath((string) $request->query('file', '')); if ($file === null) { return $this->refuse('That path is not allowed.', 422); } $raw = (new ServerFiles($server))->fileContents($file, self::MAX_NBT); if ($raw === null) { return $this->refuse('That file could not be read.', 502); /* alterexclusive */ } if (strlen($raw) > self::MAX_NBT) { return $this->refuse('That file is too large to open here.', 422); } try { [$plain, $compression] = Nbt::decompress($raw); return new JsonResponse([ 'file' => $file, 'compression' => $compression, 'tree' => Nbt::toArray(Nbt::parse($plain)), ]); } catch (Throwable) { return $this->refuse('That file is not readable NBT.', 422); } } public function saveNbt(WorldWriteRequest $request, Server $server): JsonResponse { $data = $request->validate([ 'file' => ['required', 'string', 'max:512'], 'compression' => ['required', 'string', 'in:gzip,zlib,raw'], 'tree' => ['required', 'array'], ]); $file = Worlds::safePath($data['file']); if ($file === null) { return $this->refuse('That path is not allowed.', 422); } $files = new ServerFiles($server); if ($files->powerState() !== 'offline') { return $this->refuse( 'Stop the server first. A running server keeps the world in memory and would overwrite this on its next save.', 409, ); } try { $payload = Nbt::compress(Nbt::serialize(Nbt::fromArray($data['tree'])), $data['compression']); } catch (Throwable) { return $this->refuse('That tree could not be written as NBT.', 422); } $existing = $files->fileContents($file, self::MAX_NBT); if ($existing !== null) { $files->writeFile($file.'_old', $existing); } if (!$files->writeFile($file, $payload)) { return $this->refuse('That file could not be written.', 502); } Worlds::forget($server->uuid, dirname($file)); return new JsonResponse(['saved' => true, 'backup' => $file.'_old']); } public function dimensions(WorldRequest $request, Server $server): JsonResponse { $world = Worlds::safePath((string) $request->query('path', '')); if ($world === null) { return $this->refuse('That path is not allowed.', 422); } return new JsonResponse([ 'dimensions' => Worlds::details(new ServerFiles($server), $server->uuid, $world)['dimensions'], ]); } public function regions(WorldRequest $request, Server $server): JsonResponse { $path = Worlds::safePath((string) $request->query('path', '')); if ($path === null) { return $this->refuse('That path is not allowed.', 422); } $regions = []; foreach ((new ServerFiles($server))->listFiles($path) ?? [] as $entry) { $name = (string) ($entry['name'] ?? ''); if (preg_match('/^r\.(-?\d+)\.(-?\d+)\.mca$/', $name, $match) !== 1) { continue; } $regions[] = [ 'name' => $name, 'file' => "{$path}/{$name}", 'x' => (int) $match[1], 'z' => (int) $match[2], 'size' => (int) ($entry['size'] ?? 0), 'modifiedAt' => $entry['modified_at'] ?? null, ]; } usort($regions, fn (array $a, array $b) => [$a['z'], $a['x']] <=> [$b['z'], $b['x']]); return new JsonResponse(['regions' => $regions]); } public function chunks(WorldRequest $request, Server $server): JsonResponse { $file = Worlds::safePath((string) $request->query('file', '')); if ($file === null) { return $this->refuse('That path is not allowed.', 422); } $local = RegionFile::fetch(new ServerFiles($server), $server->uuid, $file); $chunks = $local === null ? null : RegionFile::index($local); if ($chunks === null) { return $this->refuse('That region could not be read.', 502); } return new JsonResponse(['chunks' => $chunks]); } public function chunk(WorldRequest $request, Server $server): JsonResponse { $data = $request->validate([ 'file' => ['required', 'string', 'max:512'], 'offset' => ['required', 'integer', 'min:1'], 'sectors' => ['required', 'integer', 'min:1', 'max:255'], ]); $file = Worlds::safePath($data['file']); if ($file === null) { return $this->refuse('That path is not allowed.', 422); } $local = RegionFile::fetch(new ServerFiles($server), $server->uuid, $file); $chunk = $local === null ? null : RegionFile::chunk($local, (int) $data['offset'], (int) $data['sectors']); if ($chunk === null) { return $this->refuse('That chunk could not be read.', 502); } try { return new JsonResponse([ 'compression' => $chunk[1], 'tree' => Nbt::toArray(Nbt::parse($chunk[0])), ]); } catch (Throwable) { return $this->refuse('That chunk is not readable NBT.', 422); } } public function map(WorldRequest $request, Server $server): JsonResponse { $file = Worlds::safePath((string) $request->query('file', '')); if ($file === null) { return $this->refuse('That path is not allowed.', 422); } $tile = RegionFile::tilePath($server->uuid, $file); if (is_file($tile) && filesize($tile) > 0) { return new JsonResponse([ 'ready' => true, 'image' => 'data:image/png;base64,'.base64_encode((string) file_get_contents($tile)), ]); } RenderRegionMap::dispatch($server, $file, $tile); return new JsonResponse(['ready' => false]); } public function deleteChunks(WorldDeleteRequest $request, Server $server): JsonResponse { $data = $request->validate([ 'file' => ['required', 'string', 'max:512'], 'indexes' => ['required', 'array', 'min:1', 'max:1024'], 'indexes.*' => ['integer', 'min:0', 'max:1023'], ]); $file = Worlds::safePath($data['file']); if ($file === null) { return $this->refuse('That path is not allowed.', 422); } $files = new ServerFiles($server); if ($files->powerState() !== 'offline') { return $this->refuse( 'Stop the server first. A running server would rewrite these chunks from memory.', 409, ); } $local = RegionFile::fetch($files, $server->uuid, $file); if ($local === null || !RegionFile::deleteChunks($local, $data['indexes'])) { return $this->refuse('That region could not be edited.', 502); } $payload = @file_get_contents($local); if ($payload === false || !$files->writeFile($file, $payload)) { return $this->refuse('That region could not be written back.', 502); } return new JsonResponse(['deleted' => count($data['indexes'])]); } private function refuse(string $message, int $status): JsonResponse { return new JsonResponse([ 'errors' => [['code' => 'WorldViewerRefused', 'status' => (string) $status, 'detail' => $message]], ], $status); } } 